SELECT COUNT(*) FROM users as u, comments as c, posts as p, postLinks as pl, postHistory as ph, badges as b WHERE c.UserId = u.Id AND p.Id = c.PostId AND p.Id = ph.PostId AND b.UserId = u.Id AND p.Id = pl.RelatedPostId AND c.Score=0 AND c.CreationDate>='2010-07-26 17:09:48'::timestamp AND p.PostTypeId=1 AND p.AnswerCount>=0 AND p.CommentCount>=0 AND p.CommentCount<=14 AND pl.CreationDate>='2010-10-27 10:02:57'::timestamp AND pl.CreationDate<='2014-09-04 17:23:50'::timestamp AND ph.CreationDate<='2014-09-11 20:09:41'::timestamp;